# Creates a diagonal connecting the 2 at (15,0) in one direction
rows, cols = 16, 16
output = [[0 for _ in range(cols)] for _ in range(rows)]

# Starting from (15, 0) with the 2, diagonally up-right means
# going by (-1, +1): back to (14, 1), (13, 2), ... 
# which is col = row - 15

for row in range(16):
    col = row - 15
    if 0 <= col < cols and col >= 0:
        output[row][col] = 1

# Print  
for i, row in enumerate(output):
    if i == 15: print(f"15: 2 " + ' '.join('1' if c!=0 else '' for c in row))
    else: print(' '.join(str(c) if c != 0 else ' ' for c in row))

print("\nSubmitted - diagonal from 2", flush=True)

# What if I fill a triangular area?
rows, cols = 16, 16
output = [[0 for _ in range(cols)] for _ in range(rows)]

# Fill where row - col >= 2 (same as the diagonal with 1s)
for row in range(16):
    for col in range(16):
        if row - col >= 2:
            output[row][col] = 1

# Print
for i, row in enumerate(output):
    print(f"{i}: {' '.join(str(x) if x != 0 else '.' for x in row)}")

print("\nSubmitted", flush=True)

